    tryonTutorialItem7: 'If a try-on garment is too small and does not cover areas that were not exposed on the original model photo, skin in those areas may render poorly. In this case (common with bikini/underwear try-ons), switch to a better model or use a model photo that exposes the corresponding skin area.',
