    generateConfirmContent: 'Туршилтын үр дүн үүсгэхийг батлах уу?',
    tryonParsingRecommendContent: 'Зургийн сегмент нь эх зургийн элементүүдийг илүү сайн хадгална. Жишээ нь зөвхөн доод зурагтай үед сегмент асаавал дээд хэсгийг өөрчлөхгүй хадгалж чадна. Асаахгүй бол дээд хэсэг санамсаргүй өөрчлөгдөх эсвэл арилж болно.',
    tryonContinueGenerateAction: 'Үргэлжлүүлэх',
    tryonGoEnableParsingAction: 'Асаах',
    tryonRefinerHelpTitle: 'Зургийн нарийвчлалын тайлбар',
    tryonRefinerHelpFallback: 'Идэвхжүүлбэл үндсэн туршилтын дараа нэмэлт нарийвчлалын алхам ажиллаж, деталь сайжирна.',
    tryonModelHint: 'Зөвлөмж: өөр өөр модель өөр хэв маяг, чанар гаргана. Зарим модель дотуур хувцас, бикини дээр илүү сайн ажиллана.',
    tryonTutorialAction: 'Заавар',
    tryonTutorialTitle: 'Туршилтын заавар',
    tryonTutorialItem1: 'Моделийн зурагт хажуу, сууж буй зэрэг позтой зураг оруулж болно. Гэхдээ урдаас эгц зогссон поз ихэвчлэн илүү сайн үр дүнтэй.',
    tryonTutorialItem2: 'Тусдаа хувцасны зураг байхгүй бол “Дээд зураг” хэсэгт хувцастай хүний зургийг шууд оруулж болно.',
    tryonTutorialItem3: 'Хувцасны зураг олоход хэцүү бол “Тайрч оруулах”-ыг ашиглаж болно. “Хувцас ялгах” функцийг дараа нь нэмэх тул хүлээнэ үү.',
    tryonTutorialItem4: 'Үр дүнгийн чанар нь модель, зургийн чанар, дэвсгэрээс шалтгаална. Дэвсгэр энгийн, хүний эзлэх хувь их байх тусам чанар илүү сайн.',
    tryonTutorialItem5: 'Зургийн нарийвчлалын модель нь хувцас, арьсны деталийг сайжруулж чадна. Гэхдээ бүх тохиолдолд тохирохгүй, заримдаа эсрэг нөлөөтэй байж болно. Болгоомжтой ашиглаарай.',
    tryonTutorialItem6: '“Миний модель”, “Миний шүүгээ” хуудсанд байнга ашигладаг моделийн зураг, хувцсаа хадгалж болно. Ингэснээр ижил зургийг дахин дахин оруулах шаардлагагүй.',
    tryonTutorialItem7: 'Туршиж буй хувцас хэт жижиг байж, моделийн зурагт өмнө нь ил гараагүй арьсны хэсгийг бүрхэхгүй бол тухайн хэсгийн арьс муу үүсч болно. Ийм үед илүү сайн модель сонгох эсвэл тухайн хэсгийн арьс ил гарсан моделийн зураг ашиглана. Энэ нь ихэвчлэн бикини эсвэл дотуур хувцас турших үед тохиолддог.',
    tryonTutorialItem8: 'Моделийн зураг эмзэг хэсэг ил гаргасан байж болохгүй. Хэт ил задгай бол шалгалтаар унаж, үүсгэх боломжгүй болно.',
    tryonTutorialItem9: 'Цаашид өөр позын моделийн зураг, дотуур хувцас, бикини зэрэгт илүү тохирсон модельүүдийг шинэчилнэ. Платформын зарлалыг тогтмол дагана уу.',
    tryonTutorialItem10: 'Моделийн зурагт хажуу позтой зураг оруулж болно (урд зураг ихэвчлэн илүү сайн). Хэрэв дээд ба доод хувцасны бүрэн зураг байхгүй бол хувцастай хүний зургийг шууд оруулж болно (зөвхөн “Дээд зураг”-т оруулна, “Доод зураг” шаардлагагүй). Модель нь тухайн хүний дээд ба доод хувцсыг автоматаар моделийн зурагт өмсгөнө.',
