    uploadPersonDrawerStrongTip: 'Хажуу, сууж, хэвтэж буй позтой зураг мөн боломжтой ч урдаас зогсож авсан зураг илүү сайн үр дүнтэй. Хувцас халхлахгүй байхыг хичээгээрэй. Хүний эзлэх хувь их, дэвсгэр энгийн байх тусам үр дүн сайн гарна. Албан ёсны моделийн жишээг үзнэ үү.',
