    tryonTutorialAction: '教程',
    tryonTutorialTitle: '試衣教程',
    tryonTutorialItem1: '模特圖可以上傳側身姿勢、坐著姿勢等圖片，但是正面站立姿勢生成效果更佳。',
    tryonTutorialItem2: '如果沒有單獨的服裝圖片，可直接在「上裝圖」位置上傳人物穿著的圖片。',
    tryonTutorialItem3: '如果服裝圖片很難獲取，可以使用「裁剪上傳」裁剪，後續會添加「取衣」功能，敬請期待。',
    tryonTutorialItem4: '生成品質和模型、圖片品質、背景有關，背景越簡單，人物在圖片占比越大，生成品質更好。',
    tryonTutorialItem5: '圖片精修模型會提高衣物、皮膚的細節質感，但不適用所有，有時候可能適得其反，請注意使用。',
    tryonTutorialItem6: '可以在「我的模特」和「我的衣櫥」頁面上傳保存自己常用的模特圖和服裝，這樣就不用每次都上傳同樣的圖片。',
    tryonTutorialItem7: '如果試穿的服裝太小導致沒有覆蓋模特圖原來沒露出皮膚的位置，對應位置的皮膚可能生成不好，可以切換更好的模型或者更換露出對應位置皮膚的模特圖。這個場景一般是在試穿比基尼或者內衣。',
    tryonTutorialItem8: '模特圖不能露出敏感位置，太裸露會審核生成失敗。',
    tryonTutorialItem9: '以後會更新對不同姿勢模特圖、內衣、比基尼等生成更好的模型，請隨時關注平台公告。',
    tryonTutorialItem10: '模特圖可以上傳側身圖（正面照一般效果更好）。如果沒有完整的上裝和下裝圖，可以直接上傳人物穿著圖（上傳到上裝圖即可，不用傳下裝圖），模型會自動把該人物的上下身服裝試穿到模特圖上。',
