    tryonTutorialItem4: 'คุณภาพผลลัพธ์ขึ้นกับโมเดล คุณภาพรูป และพื้นหลัง ยิ่งพื้นหลังเรียบและคนมีสัดส่วนใหญ่ในภาพ ผลลัพธ์มักยิ่งดี',
    tryonTutorialItem5: 'โมเดลปรับภาพละเอียดช่วยเพิ่มรายละเอียดของเสื้อผ้าและผิว แต่ไม่เหมาะกับทุกกรณี และบางครั้งอาจให้ผลตรงข้าม ควรใช้อย่างระมัดระวัง',
    tryonTutorialItem6: 'คุณสามารถอัปโหลดและบันทึกรูปโมเดลและเสื้อผ้าที่ใช้บ่อยไว้ใน "โมเดลของฉัน" และ "ตู้เสื้อผ้าของฉัน" เพื่อไม่ต้องอัปโหลดซ้ำทุกครั้ง',
    tryonTutorialItem7: 'หากเสื้อผ้าที่ลองมีขนาดเล็กจนไม่ครอบคลุมบริเวณผิวที่เดิมไม่ได้เปิดเผยในรูปโมเดล ผิวบริเวณนั้นอาจสร้างได้ไม่ดี กรณีนี้ (มักเกิดกับบิกินี/ชุดชั้นใน) ให้เปลี่ยนโมเดลที่ดีกว่า หรือใช้รูปโมเดลที่เปิดผิวในตำแหน่งนั้น',
    tryonTutorialItem8: 'รูปโมเดลต้องไม่เผยตำแหน่งที่อ่อนไหว หากโป๊มากเกินไปอาจตรวจไม่ผ่านและสร้างไม่สำเร็จ',
    tryonTutorialItem9: 'ในอนาคตจะมีการอัปเดตโมเดลที่ดีกว่าสำหรับท่าทางต่าง ๆ และสำหรับชุดชั้นใน/บิกินี โปรดติดตามประกาศแพลตฟอร์ม',
    tryonTutorialItem10: 'สามารถอัปโหลดรูปโมเดลมุมข้างได้ (โดยทั่วไปรูปด้านหน้าจะได้ผลดีกว่า) หากไม่มีรูปท่อนบนและท่อนล่างครบ สามารถอัปโหลดรูปคนที่สวมชุดได้โดยตรง (อัปโหลดเฉพาะช่อง "รูปบน" ไม่ต้องอัปโหลดท่อนล่าง) ระบบจะลองสวมเสื้อผ้าท่อนบนและท่อนล่างของคนนั้นให้โมเดลโดยอัตโนมัติ',
