    tryonModelHint: 'सुझाव: अलग-अलग मॉडल अलग स्टाइल और क्वालिटी देते हैं। कुछ मॉडल इनरवियर और बिकिनी इमेज के लिए बेहतर होते हैं।',
    tryonTutorialAction: 'गाइड',
    tryonTutorialTitle: 'ट्राय-ऑन गाइड',
    tryonTutorialItem1: 'मॉडल फोटो में साइड पोज़, बैठी हुई पोज़ आदि अपलोड की जा सकती हैं, लेकिन सामने सीधा खड़ा पोज़ सामान्यतः बेहतर परिणाम देता है।',
    tryonTutorialItem2: 'अगर अलग कपड़ों की फोटो नहीं है, तो "ऊपरी चित्र" स्लॉट में पहने हुए व्यक्ति की फोटो सीधे अपलोड कर सकते हैं।',
    tryonTutorialItem3: 'अगर कपड़ों की फोटो मिलना कठिन हो, तो "क्रॉप अपलोड" का उपयोग करें। आगे "कपड़ा निकालें" फीचर जोड़ा जाएगा।',
    tryonTutorialItem4: 'जनरेशन क्वालिटी मॉडल, इमेज क्वालिटी और बैकग्राउंड पर निर्भर है। बैकग्राउंड जितना सरल और व्यक्ति का अनुपात जितना बड़ा होगा, परिणाम उतने बेहतर होंगे।',
    tryonTutorialItem5: 'इमेज रिफाइनर मॉडल कपड़ों और त्वचा की डिटेल बढ़ा सकता है, लेकिन हर केस में उपयुक्त नहीं होता और कभी-कभी उल्टा असर भी दे सकता है; सावधानी से उपयोग करें।',
    tryonTutorialItem6: 'आप "मेरे मॉडल" और "मेरी अलमारी" में अक्सर उपयोग होने वाली मॉडल/कपड़ों की तस्वीरें सेव कर सकते हैं, ताकि हर बार वही तस्वीरें दोबारा अपलोड न करनी पड़ें।',
    tryonTutorialItem7: 'अगर ट्राई-ऑन कपड़ा बहुत छोटा है और मॉडल फोटो के उन हिस्सों को कवर नहीं करता जो पहले एक्सपोज़ नहीं थे, तो उन हिस्सों की त्वचा खराब जनरेट हो सकती है। यह स्थिति आमतौर पर बिकिनी/इनरवियर ट्राई-ऑन में होती है; ऐसे में बेहतर मॉडल चुनें या उस हिस्से की त्वचा एक्सपोज़ करने वाली मॉडल फोटो इस्तेमाल करें।',
    tryonTutorialItem8: 'मॉडल फोटो में संवेदनशील हिस्से नहीं दिखने चाहिए। बहुत अधिक खुली फोटो समीक्षा में फेल होकर जनरेशन विफल कर सकती है।',
    tryonTutorialItem9: 'आगे अलग-अलग पोज़, इनरवियर और बिकिनी जैसे परिदृश्यों के लिए बेहतर मॉडल अपडेट किए जाएंगे; प्लेटफ़ॉर्म घोषणाएँ देखते रहें।',
    tryonTutorialItem10: 'मॉडल फोटो साइड-व्यू में भी अपलोड की जा सकती है (फ्रंट-व्यू आमतौर पर बेहतर रहता है)। अगर आपके पास पूरा ऊपरी और निचला कपड़ों का सेट नहीं है, तो पहने हुए व्यक्ति की फोटो सीधे अपलोड करें (सिर्फ "ऊपरी चित्र" में, "निचला चित्र" जरूरी नहीं)। मॉडल उस व्यक्ति के ऊपरी और निचले कपड़ों को अपने-आप मॉडल फोटो पर ट्राई करेगा।',
