    uploadDrawerTipPerson: 'यहाँ अपलोड करें, मेरे मॉडल से चुनें, या आधिकारिक मॉडल उदाहरण उपयोग करें।',
    uploadDrawerTipClothes: 'यहाँ कपड़ों की तस्वीर अपलोड करें, या सुझाए गए उदाहरण और मेरी अलमारी से ऑटो-फिल करें।',
    uploadDrawerTipShoes: 'यहाँ जूतों की तस्वीर अपलोड करें, या सुझाए गए उदाहरण पर टैप करके ऑटो-फिल करें।',
    uploadDrawerEmptyPersonToMyModel: 'आपके पास अभी कोई मॉडल नहीं है। कृपया "मेरे मॉडल" पेज पर जाकर जोड़ें।',
    uploadDrawerEmptyClothesToMyCloset: 'आपने अभी कुछ नहीं जोड़ा है। कृपया "मेरी अलमारी" पेज पर जाकर जोड़ें।',
    uploadPersonDrawerStrongTip: 'साइड, बैठी या लेटी हुई फोटो भी काम करती हैं, लेकिन सामने से खड़ी फोटो आमतौर पर बेहतर रहती है। कपड़े ढके न हों। व्यक्ति का हिस्सा बड़ा और बैकग्राउंड सरल हो तो परिणाम बेहतर आता है। आधिकारिक मॉडल उदाहरण देखें।',
    uploadUpperDrawerStrongTip: 'यदि वन-पीस पोशाक है तो केवल ऊपरी चित्र पर्याप्त है। यदि अलग कपड़े की फोटो नहीं है, तो ऊपरी स्लॉट में पहने हुए व्यक्ति की फोटो भी अपलोड कर सकते हैं। सामने से खड़ी फोटो बेहतर रहती है और कपड़े ढके न हों।',
