    generateConfirmContent: 'Apakah Anda yakin ingin menghasilkan hasil try-on?',
    tryonParsingRecommendContent: 'Parsing gambar membantu mempertahankan elemen asli dengan lebih baik. Contohnya, saat hanya ada gambar bawahan, mengaktifkan parsing dapat menjaga atasan tetap. Jika tidak diaktifkan, atasan bisa berubah acak atau hilang.',
    tryonContinueGenerateAction: 'Lanjutkan',
    tryonGoEnableParsingAction: 'Aktifkan Parsing',
    tryonRefinerHelpTitle: 'Penjelasan Penyempurna Gambar',
    tryonRefinerHelpFallback: 'Saat diaktifkan, langkah penyempurnaan tambahan dijalankan setelah try-on dasar untuk meningkatkan detail.',
    tryonModelHint: 'Tips: model yang berbeda menghasilkan gaya dan kualitas yang berbeda. Beberapa model lebih cocok untuk gambar pakaian dalam dan bikini.',
    tryonTutorialAction: 'Panduan',
    tryonTutorialTitle: 'Panduan Try-On',
    tryonTutorialItem1: 'Foto model boleh berupa pose samping, duduk, dan sebagainya, tetapi pose berdiri menghadap depan biasanya memberi hasil lebih baik.',
    tryonTutorialItem2: 'Jika tidak ada foto pakaian terpisah, Anda bisa langsung unggah foto orang yang sedang memakai pakaian pada slot "Atasan".',
    tryonTutorialItem3: 'Jika foto pakaian sulit didapat, gunakan "Unggah Potong" terlebih dahulu. Fitur "Ekstraksi Pakaian" akan ditambahkan nanti.',
    tryonTutorialItem4: 'Kualitas hasil bergantung pada model, kualitas gambar, dan latar belakang. Semakin sederhana latar belakang dan semakin besar proporsi orang di gambar, biasanya hasil semakin baik.',
    tryonTutorialItem5: 'Model penyempurna gambar dapat meningkatkan detail pakaian dan kulit, tetapi tidak cocok untuk semua kasus dan kadang bisa memberi hasil sebaliknya. Gunakan dengan hati-hati.',
    tryonTutorialItem6: 'Anda dapat menyimpan foto model dan pakaian yang sering dipakai di halaman "Model Saya" dan "Lemari Saya" agar tidak perlu unggah gambar yang sama setiap kali.',
    tryonTutorialItem7: 'Jika pakaian try-on terlalu kecil sehingga tidak menutupi area kulit yang sebelumnya tidak terekspos pada foto model, kulit di area tersebut bisa tergenerasi kurang baik. Kondisi ini umum saat mencoba bikini atau pakaian dalam; Anda bisa mengganti ke model yang lebih baik atau memakai foto model yang mengekspos area kulit terkait.',
    tryonTutorialItem8: 'Foto model tidak boleh menampilkan area sensitif. Foto yang terlalu terbuka dapat gagal moderasi dan gagal generate.',
    tryonTutorialItem9: 'Ke depannya kami akan terus memperbarui model yang lebih baik untuk berbagai pose model serta skenario pakaian dalam/bikini. Pantau pengumuman platform.',
    tryonTutorialItem10: 'Foto model bisa diunggah dari samping (foto depan biasanya lebih baik). Jika Anda tidak memiliki gambar atasan dan bawahan yang lengkap, Anda dapat langsung unggah foto orang yang sedang berpakaian (cukup ke slot "Atasan", tidak perlu slot bawahan). Model akan otomatis mencoba pakaian atas dan bawah orang tersebut pada foto model.',
